SELECT question_id,version,product,dimension,response_type,required_flag,minimum_value,maximum_value,weight,score_direction,status FROM gv1_question_definitions WHERE question_id='triage.problem_clarity' AND version='v1'; SELECT answer_id,bmr_id,session_id,question_id,question_version,answer_group_id,version_no,supersedes_answer_id,raw_value_number,normalized_value_number,source,captured_at,status,content_hash FROM gv1_assessment_answers WHERE answer_id IN ('ans_554a7fe2171d47d183088bb3ebbcaa9a','ans_8e15a2d9e75f4089ae7b8aab5ac8d2a6') ORDER BY version_no; SELECT evidence_id,bmr_id,session_id,evidence_group_id,version_no,supersedes_evidence_id,source_type,source_ref,value_type,value_number,status,consent_status,captured_at,content_hash FROM gv1_evidence_items WHERE evidence_id IN ('evd_e56233001af044e3b442c5f340bb57ba','evd_9a171900bc904d6c89b0685853f4d68d') ORDER BY version_no; SELECT COUNT(*) AS lineage FROM gv1_evidence_relationships WHERE from_evidence_id='evd_9a171900bc904d6c89b0685853f4d68d' AND to_evidence_id='evd_e56233001af044e3b442c5f340bb57ba' AND relationship_type='corrects'; SELECT COUNT(*) AS v1_successors FROM gv1_evidence_items WHERE supersedes_evidence_id='evd_e56233001af044e3b442c5f340bb57ba'; SELECT COUNT(*) AS rejected FROM gv1_evidence_items WHERE evidence_id='evd_6b6fe1f262164faa870b3a3e5e04c8e5' AND status='rejected'; SELECT processed_count,imported_count,skipped_count,error_count,status FROM gv1_import_batches WHERE import_batch_id='imp_2bd2db76b8cd49169851691692c83394'; SELECT COUNT(*) AS import_receipts FROM gv1_import_row_receipts WHERE import_batch_id='imp_2bd2db76b8cd49169851691692c83394'; SELECT COUNT(*) AS import_errors FROM gv1_import_errors WHERE import_batch_id='imp_2bd2db76b8cd49169851691692c83394'; SELECT COUNT(*) AS immutable_trigger FROM sqlite_master WHERE type='trigger' AND name='trg_gv1_accepted_evidence_no_update';
